Think: For each .txt path listed, count lines or log read errors, writing counts to temp_workspace/line_counts.csv and errors to temp_workspace/errors.log — do this in one awk command that safely handles unreadable files.

Act: bash

```bash
awk '{
 fname=$0;
 r = (getline line < fname);
 if (r < 0) {
   print "ERROR: cannot read " fname > "temp_workspace/errors.log";
 } else {
   c = r;
   while ((getline line < fname) > 0) c++;
   print fname "," c;
 }
 close(fname);
}' temp_workspace/txt_file_list.txt > temp_workspace/line_counts.csv
