Think: Run a consistency check for each level1 directory by listing its immediate subdirectories and comparing them to the expected level2_1 and level2_2, writing results to consistency_report.txt.

Act: bash

```bash
printf 'level1_A\nlevel1_B\nlevel1_C\n' | awk '{
 p=$0;
 cmd = "find /tmp/parentDir/" p " -mindepth 1 -maxdepth 1 -type d -printf \"%f\\n\" 2>/dev/null";
 n=0; seen1=0; seen2=0;
 while ((cmd | getline child) > 0) {
   n++; children[n]=child;
   if(child=="level2_1") seen1=1;
   if(child=="level2_2") seen2=1;
 }
 close(cmd);
 if(n==2 && seen1 && seen2) {
   print p ": OK";
 } else {
   printf p ": MISMATCH: found {";
   for(i=1;i<=n;i++){ printf children[i]; if(i<n) printf "," }
   print "}";
   if(!seen1) print "  Missing: level2_1";
   if(!seen2) print "  Missing: level2_2";
   if(n>2) print "  Unexpected count: " n;
 }
 delete children;
 }' > /tmp/parentDir/consistency_report.txt
```

