Think: Verify each recorded count by comparing to actual lines in matches files and write results to verification_log.txt.

Act: bash

```bash
awk '{
 expected=$2;
 file="temp_workspace/matches_"$1;
 cmd="wc -l < \"" file "\"";
 cmd | getline actual;
 close(cmd);
 out="temp_workspace/verification_log.txt";
 if(NR==1){
   if(actual+0==expected+0) print $1, "CONFIRMED", expected > out;
   else print $1, "MISMATCH: recorded=" expected " actual=" actual > out;
 } else {
   if(actual+0==expected+0) print $1, "CONFIRMED", expected >> out;
   else print $1, "MISMATCH: recorded=" expected " actual=" actual >> out;
 }
}' temp_workspace/counts_per_file.txt
