Think: For each listed employee file, extract lines starting with "urgent:" into temp_workspace/urgent_{id}.txt and log files with no urgent lines into temp_workspace/no_urgent_log.txt. I'll run a single awk command that processes temp_workspace/file_list.txt, reads each employee file, creates/truncates urgent files as needed, and produces/clears the no_urgent_log.txt.

Act: bash

```bash
awk -v dir="temp_workspace" 'BEGIN{ nlog=dir "/no_urgent_log.txt"; system("rm -f " nlog) }
{
 name=substr($0,3);
 id=name; sub(/\.txt$/,"",id);
 infile=dir "/" name;
 ufile=dir "/urgent_" id ".txt";
 found=0;
 while((getline line < infile) > 0){
   if(line ~ /^urgent:/){
     if(!(ufile in seen)){ print line > ufile; seen[ufile]=1 } else { print line >> ufile }
     found=1;
   }
 }
 close(infile);
 if(found==0) print name >> nlog;
}' temp_workspace/file_list.txt
