Think: Normalize IP-like tokens from temp_workspace/extracted_ips_raw.txt into canonical IPv4 form, writing valid normalized addresses to temp_workspace/normalized_ips.txt and invalid entries to temp_workspace/malformed_ips.log.

Act: bash

```bash
awk 'BEGIN{ system("printf \"\" > temp_workspace/normalized_ips.txt"); system("printf \"\" > temp_workspace/malformed_ips.log") }
{
 ip=$NF;
 gsub(/^[^0-9.]*/, "", ip);
 gsub(/[^0-9.]*$/, "", ip);
 n=split(ip,a,"\\.");
 if(n==4){
  valid=1;
  for(i=1;i<=4;i++){
    if(a[i]=="" || a[i]!~ /^[0-9]+$/){ valid=0; break }
    num = a[i] + 0;
    if(num<0 || num>255){ valid=0; break}
    a[i]=num
  }
  if(valid){
    print a[1]"."a[2]"."a[3]"."a[4] >> "temp_workspace/normalized_ips.txt"
  } else {
    print $0 >> "temp_workspace/malformed_ips.log"
  }
 } else {
  print $0 >> "temp_workspace/malformed_ips.log"
 }
}' temp_workspace/extracted_ips_raw.txt
```

